mapper.select:
SELECT a.T_SUBJECT_CODE_3, a.T_SUBJECT_TYPE, ( SELECT enum_dscr FROM enumset.cm_guoku_enumeration WHERE enum_type_id = '32' AND enum_id = a.T_SUBJECT_TYPE ) AS T_SUBJECT_TYPE_DSCR, a.STAT_CODE_4, a.SUBJECT_CODE_4, a.SUBJECT_DSCR_4, a.BUDGET_TYPE, ( SELECT enum_dscr FROM enumset.cm_guoku_enumeration WHERE enum_type_id = '33' AND enum_id = a.BUDGET_TYPE ) AS BUDGET_TYPE_DSCR, a.S_BDGSBTVSION, a.FLITTING_FLAG, ( SELECT enum_dscr FROM enumset.cm_guoku_enumeration WHERE enum_type_id = '34' AND enum_id = a.FLITTING_FLAG ) AS FLITTING_FLAG_DSCR, ADD_USER, ADD_DATE FROM `ods`.cm_guoku_subject_import a WHERE 1 = 1
and a.S_BDGSBTVSION = #{params.S_BDGSBTVSION}
and a.BUDGET_TYPE = #{params.BUDGET_TYPE}
and a.SUBJECT_CODE_4 = #{params.SUBJECT_CODE_4}
and a.SUBJECT_DSCR_4 like '%${params.SUBJECT_DSCR_4}%'
and a.T_SUBJECT_TYPE = #{params.T_SUBJECT_TYPE}
ORDER BY a.S_BDGSBTVSION desc,SUBJECT_CODE_4 asc LIMIT ${params.page},${params.rows}

